parameters.jsCode:
const raw = $('RECIBE_DATA').first().json.body ? $('RECIBE_DATA').first().json.body : $('RECIBE_DATA').first().json;

let aiText = "";
try {
  const aiRes = $input.first().json;
  if (aiRes.content && aiRes.content.parts && aiRes.content.parts[0]) {
    aiText = aiRes.content.parts[0].text || "";
  } else if (aiRes.candidates && aiRes.candidates[0] && aiRes.candidates[0].content) {
    aiText = aiRes.candidates[0].content.parts[0].text || "";
  } else if (raw.ai_summary) {
    aiText = raw.ai_summary;
  }
} catch (e) {
  aiText = raw.ai_summary || "";
}

function stripHTML(text) {
  if (!text) return "";
  return String(text)
    .replace(/<[^>]*>/g, "")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&amp;/g, "&")
    .trim();
}

const rawSev = raw.severidad || raw.severity || raw.nivel || "";
const sevUpper = String(rawSev).toUpperCase();

let emoji = "⚠️";
if (sevUpper.includes("CRITIC") || sevUpper.includes("CRÍT")) emoji = "🚨";
else if (sevUpper.includes("HIGH") || sevUpper.includes("ALTA")) emoji = "🛑";
else if (sevUpper.includes("INFO") || sevUpper.includes("BAJ")) emoji = "ℹ️";
else if (sevUpper.includes("MED")) emoji = "🟡";

const severidad = stripHTML(rawSev) || "HIGH";
const scoreVal = raw.risk_score || raw.score || "8.0";
const scoreNum = parseFloat(scoreVal) || 8.0;
const evento = stripHTML(raw.tipo_incidente || raw.event_type || raw.evento) || "Incidente de Ciberseguridad";
const activo = stripHTML(raw.activo_afectado || raw.affected_asset || raw.recurso) || "Infraestructura Alma";
const control = stripHTML(raw.control_nist || raw.framework_nist || raw.nist_control) || "NIST CSF v2.0";
const ip = stripHTML(raw.ip || raw.attacker_ip || raw.responsable_ip || raw.ip_origen) || "N/A";
const sensor = stripHTML(raw.source || raw.origen || raw.fuente) || "Sensor Perimetral";
const detalle = stripHTML(raw.detalles_tecnicos || raw.detalles || raw.details) || "Sin detalles adicionales.";
let id = stripHTML(raw.incident_id || raw.id_incidente || "");
if (!id || id === "ALMA-SEC-DISPATCH" || id === "N/A" || id === "ALMA-SEC-UNKNOWN") {
  const randHex = Math.random().toString(36).substring(2, 8).toUpperCase();
  id = "ALMA-INC-" + Date.now().toString().slice(-4) + "-" + randHex;
}

// Hora oficial de Lima, Perú
const ahoraPeru = new Date().toLocaleString("sv-SE", { 
  timeZone: "America/Lima" 
}).replace("T", " ");

// 1. Clasificación Contextual Dinámica
const textoEvento = (evento + " " + sensor).toLowerCase();
const esShiftLeft = textoEvento.includes("shift") || textoEvento.includes("secretos") || textoEvento.includes("commit") || textoEvento.includes("gitleaks");
const esAuditoria = textoEvento.includes("auditor") || textoEvento.includes("escaneo") || textoEvento.includes("diagnostico");
const esTraficoPermitido = textoEvento.includes("whitelist") || textoEvento.includes("opengraph") || severidad === "INFO";

let tituloAlerta = "ALERTA SOC";
let lineaOrigen = "";

if (esShiftLeft) {
  tituloAlerta = "BLOQUEO PREVENTIVO GIT";
  lineaOrigen = "• Desarrollador: " + (raw.user_involved || raw.responsable || "Estación Local") + "\n";
} else if (esTraficoPermitido) {
  tituloAlerta = "TRÁFICO VERIFICADO";
  lineaOrigen = "• Rastreador: " + (raw.user_involved || "Bot en Whitelist") + "\n";
} else if (esAuditoria) {
  tituloAlerta = "AUDITORÍA PERIMETRAL";
  lineaOrigen = "• Sensor: " + sensor + "\n" + (ip && ip !== "N/A" && !ip.includes("Auditoria") ? "• IP Auditada: " + ip + "\n" : "");
} else {
  tituloAlerta = "INCIDENTE PERIMETRAL";
  lineaOrigen = "• IP Atacante: " + ip + " 🚨\n";
}

let seccionIa = "";
if (aiText && aiText.length > 5) {
  seccionIa = "\n🧠 TRIAGE IA (Gemini):\n" + stripHTML(aiText).trim() + "\n";
}

// 2. Mensaje Ejecutivo y Compacto
const mensajeFinal = (
  emoji + " " + tituloAlerta + " | ALMA DEVSECOPS\n" +
  "━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n" +
  "• Evento: " + evento + "\n" +
  "• Criticidad: " + severidad + " (" + scoreNum + "/10) | " + control + "\n" +
  lineaOrigen +
  "• Activo: " + activo + "\n" +
  seccionIa + "\n" +
  "⏱️ ID: " + id + " | " + ahoraPeru
).trim();

return [{
  json: {
    text: mensajeFinal,
    codigo_incidente: id,
    fecha_registro: ahoraPeru,
    tipo_evento: evento,
    severidad: severidad,
    risk_score: scoreNum,
    origen_sensor: sensor,
    ip_origen: ip,
    activo_afectado: activo,
    detalles_tecnicos: detalle,
    control_nist: control,
    procedimiento_sop: raw.sop_reference || raw.sop || "SOP-03",
    resumen_ia: aiText || "Triage aplicado",
    acciones_recomendadas: raw.suggested_action || "Mitigación ejecutada",
    estado_incidente: "ABIERTO",
    mitigado_en: null,
    inicio_ms: Date.now()
  }
}];

// Módulo de Auditoría y Bitácora de Incidentes (NIST CSF v2.0: DE.CM-01 / Ley N° 29733)
const item = $input.first().json;

const logEntry = {
  registro_timestamp: new Date().toISOString(),
  id_incidente: item.incident_id,
  tipo_evento: item.event_type,
  severidad: item.severity,
  score_riesgo: item.risk_score,
  activo_custodiado: item.affected_asset,
  ip_origen: item.ip_source,
  control_aplicado: item.nist_control,
  procedimiento_sop: item.sop_reference,
  triage_ia_resultado: item.ai_analysis,
  cumplimiento_ley_29733: "TRAZABILIDAD_GARANTIZADA",
  estado_alerta: "DESPACHADA_A_TELEGRAM"
};

console.log("[AUDITORIA NIST DE.CM-01] Incidente registrado en bitacora:", JSON.stringify(logEntry));

return [{ json: logEntry }];
